from __future__ import annotations
import cmath
import math

def collatz_fourier(cutoff: int, omega: float, odd_multiplier: int = 3) -> complex:
    """Evaluate the generalized finite Collatz exponential sum."""
    if cutoff < 1:
        raise ValueError("cutoff must be positive")
    even = (cutoff // 2) * cmath.exp(1j * math.pi * omega)
    odd = sum(cmath.exp(2j * math.pi * omega / n) for n in range(1, cutoff + 1, 2))
    return even + cmath.exp(2j * math.pi * odd_multiplier * omega) * odd

def direct(cutoff: int, omega: float) -> complex:
    def step(n: int) -> int:
        return n // 2 if n % 2 == 0 else 3 * n + 1
    return sum(cmath.exp(2j * math.pi * omega * step(n) / n)
               for n in range(1, cutoff + 1))

if __name__ == "__main__":
    N: int = 500
    for omega in (0.0, math.sqrt(2.0) / 100, 0.37, 1.0):
        a: complex = direct(N, omega)
        b: complex = collatz_fourier(N, omega)
        assert abs(a - b) < 1e-9
        assert abs(b) <= N + 1e-9
        print(omega, abs(b), abs(a - b))

