from __future__ import annotations
import cmath
import math

def direct_sum(cutoff: int, omega: float) -> complex:
    if cutoff < 1:
        raise ValueError("cutoff must be positive")
    total: complex = 0j
    for n in range(1, cutoff + 1):
        image: int = n // 2 if n % 2 == 0 else 3 * n + 1
        total += cmath.exp(2j * math.pi * omega * image / n)
    return total

if __name__ == "__main__":
    print(direct_sum(1000, 0.01))

