def off_resonance_scan(cutoff: int, start: float, stop: float,
                       samples: int, delta: float) -> list[tuple[float, float]]:
    if samples < 2 or not 0.0 <= delta <= 0.5:
        raise ValueError("invalid grid parameters")
    output: list[tuple[float, float]] = []
    for j in range(samples):
        omega: float = start + j * (stop - start) / (samples - 1)
        distance: float = abs(omega - round(omega))
        if distance >= delta:
            output.append((omega, abs(collatz_fourier(cutoff, omega)) / cutoff))
    return output

